} catch (err) {
	console.log(err.message)
}

inlineScript.scriptBlock:
// on change of tenorBaseDate, tenorMaturityDate, tenorDays
// Guard against recursive calls
this.isCalculating = false;
this.setInstalmentCalculations = function (ind, caller) {
	if (this.isCalculating == true) {
		return;
	}

	try {
		this.isCalculating = true;

		const tenorTable = this.getFieldById("Table1");
		const baseDate = tenorTable.ui.getChild("instalmentBaseDate", ind);
		const maturityDate = tenorTable.ui.getChild("instalmentMaturityDate", ind);
		const tenorDays = tenorTable.ui.getChild("instalmentTenorDays", ind);

		const baseDateValue = baseDate.getData() ? getDateOnly(baseDate.getDate()) : null;
		const maturityDateValue = maturityDate.getData() ? getDateOnly(maturityDate.getDate()) : null;
		const tenorDaysValue = tenorDays.getData() || 0;

		// Recalculate Maturity Date when Tenor Days change
		if (baseDateValue && (caller == "t" || caller == "b")) {
			const newMaturityDate = new Date(baseDateValue);
			newMaturityDate.setDate(baseDateValue.getDate() + tenorDaysValue);
			maturityDate.setDate(newMaturityDate);
		}
		// Recalculate Tenor Days when Maturity Date changes
		else if (maturityDateValue && baseDateValue && caller == "m") {
			const recalculatedTenor = Math.floor((maturityDateValue.getTime() - baseDateValue.getTime()) / (1000 * 60 * 60 * 24));
			tenorDays.setData(recalculatedTenor > 0 ? recalculatedTenor : 0);
		}
	} finally {
		// Always reset the flag when done, even if an error occurs
		this.isCalculating = false;
	}
};

// on change tenorMaturityDate
this.passMaturityDate = function () {
	if (page.ui.get("/DC_Templete1/7/maturityDate")) {
		page.ui.get("/DC_Templete1/7").matDateController("");
	}
};

this.showOurCharges = function () {
	if (this.context.options.requestType.get("value") == "create" || this.context.options.requestType.get("value") == "amend" || this.context.options.requestType.get("value") == "recreate") {
		this.ui.get("ourCharges").setVisible(true, false);
	} else this.ui.get("ourCharges").setVisible(false, false);
};
// on load of amountCollectableByNBE and oc change of documentAmount, amountAdvanced, discount, extraCharges, contractRebate
this.amountCollectableByNBE = function () {
	var isAmendOrCollec = this.context.options.requestType.get("value").toLowerCase().includes("amend") || this.context.options.requestType.get("value").toLowerCase().includes("collection");
	var isPositionScreen = this.context.options.positionSearch?.get("value") == true;
	if (isPositionScreen) return; // do not calculate on position screen
	if (isAmendOrCollec) return; // do not calculate on amend or collection screen

	var sum = 0;
	var docAmount = this.context.options.documentAmount.get("value") || 0;
	var advAmount = this.context.options.amountAdvanced.get("value") || 0;
	var discount = this.context.binding.get("value").get("discount") || 0;
	var extraCharges = this.context.binding.get("value").get("extraCharges") || 0;
	sum = docAmount - discount + extraCharges - advAmount;
	this.context.binding.get("value").set("collectableAmount", sum);
};

this.calculateOutstandingAmount = function () {
	var isAmendOrCollec = this.context.options.requestType.get("value").toLowerCase().includes("amend") || this.context.options.requestType.get("value").toLowerCase().includes("collection");
	var isPositionScreen = this.context.options.positionSearch?.get("value") == true;
	if (isPositionScreen) return; // do not calculate on position screen
	if (isAmendOrCollec) return; // do not calculate on amend or collection screen
	if (this.context.options.requestType.get("value").toLowerCase().includes("create")) {
		var collectableAmount = this.context.binding.get("value").get("collectableAmount") || 0;
		this.context.binding.get("value").set("outstandingAmount", collectableAmount);
	}
};

this.checkPartialAvalization = function () {
	var noAvalization = this.ui.get("amountDefNoAvalization").getData();
	var avalization = this.ui.get("amountDefAvalization").getData();
	if (avalization > 0 && noAvalization > 0) {
		this.ui.get("amountDefNoAvalization").setValid(false, "Partial Avalization is not allowed, All the deferred amount must be in either Amount Deferred - No Aval. or Amount Deferred - Aval.");
		this.ui.get("amountDefAvalization").setValid(false, "Partial Avalization is not allowed, All the deferred amount must be in either Amount Deferred - No Aval. or Amount Deferred - Aval.");
	} else {
		this.ui.get("amountDefNoAvalization").setValid(true);
		this.ui.get("amountDefAvalization").setValid(true);
	}
};

//===========================================================================================
this.maturityDate = function (value) {
	this.ui.get("Table1").setVisible(false, true);
	this.context.options.multiTenorDatesVIS.set("value", "None");
	if (!value) return;
	var maturityDate = this.ui.get("maturityDate1");
	// maturityDate.setEnabled(true);

	//Deferred or sight
	/*	if (["001", "002", "003"].includes(value)) {
	//	maturityDate.setEnabled(true);
		this.context.binding.get("value").set("multiTenorDates", []);
	}*/

	//No payment
	if (value == "005") {
		//maturityDate.setEnabled(false);
		// overwrite noOfDaysMaturity

		this.context.binding.get("value").set("noOfDaysMaturity", 0);
		maturityDate.setDate();
		this.context.binding.get("value").set("multiTenorDates", []);
	}
	//multi-tenor
	else if (value == "004") {
		//maturityDate.setEnabled(true);
		this.context.options.multiTenorDatesVIS.set("value", "Editable");
		this.ui.get("Table1").setVisible(true);
		// this.ui.get("Table1").setEnabled(this.isMaker);
	} else {
		this.context.binding.get("value").set("multiTenorDates", []);
	}
	// console.dir(this.context.binding.get("value").get("multiTenorDates"));
};

this.setMaturityDate = function () {
	// Retrieve the list of multiTenorDates
	var multiTenorDates = this.context.binding.get("value").get("multiTenorDates");
	var maturityDate = this.ui.get("maturityDate1");

	// Initialize with the first date
	var minDt = multiTenorDates.get(0).get("instalmentMaturityDate");
	var minDtObj = new Date(minDt);

	// Loop through the remaining dates and find the minimum
	for (var i = 1; i < multiTenorDates.length(); i++) {
		var dt = multiTenorDates.get(i).get("instalmentMaturityDate");
		var currenDtObj = new Date(dt);

		// Compare current date with the minimum date
		if (currenDtObj < minDtObj) {
			minDt = dt;
			minDtObj = currenDtObj;
		}
	}
	// Set the maturity date to the minimum date found
	maturityDate.setDate(minDt);
};

this.setNoOfDaysMaturity = function () {
	var maturityDate = this.ui.get("maturityDate1");
	var noOfDaysMaturity = this.ui.get("noOfDaysMaturity1");
	var creationDate = this.context.options.creationDate.get("value");
	var paymentTerm = bpmext.ui.getView("/DC_Templete1/0/paymentTerms")?.getData()?.name;
	// console.log("setNoOfDaysMaturity");
	// console.log(paymentTerm);
	if (!!maturityDate.getData() && paymentTerm && paymentTerm != "005") {
		var numOfDays = Math.ceil((+maturityDate.getData() - +creationDate) / 8.64e7);
		//		alert(Math.ceil((+maturityDate.getData() - +creationDate) / 8.64e7));
		noOfDaysMaturity.setData(numOfDays);
	}
};

this.setInstalmentMaturityDate = function (ind) {
	var baseDate = this.context.binding.get("value").get("multiTenorDates").get(ind).get("instalmentBaseDate");
	var tenorDays = this.context.binding.get("value").get("multiTenorDates").get(ind).get("instalmentTenorDays");
	//var todayDate = this.context.options.todayDate.get("value");
	function addDaysToDate(date, days) {
		var result = new Date(date);
		result.setDate(result.getDate() + days);
		return result;
	}
	if (baseDate) {
		var base = new Date(baseDate);
		base.setHours(0, 0, 0, 0);

		var today = new Date();
		today.setHours(0, 0, 0, 0);
		if (base > today) {
			// this.ui.get("/DC_Templete1/4/Table1/instalmentBaseDate[" + ind + "]").setValid(false, "Base date must be <= today's date");
		} else {
			// this.ui.get("/DC_Templete1/4/Table1/instalmentBaseDate[" + ind + "]").setValid(true);

			if (tenorDays < 0) {
				this.ui.get("/DC_Templete1/4/Table1/instalmentTenorDays[" + ind + "]").setValid(false, "Invalid Value, This field can not have a negative value");
				this.context.binding.get("value").get("multiTenorDates").get(ind).set("instalmentMaturityDate", null);
			} else {
				this.ui.get("/DC_Templete1/4/Table1/instalmentTenorDays[" + ind + "]").setValid(true);
				var newMaturityDate = new Date(baseDate.getTime());
				var newMaturityDate = addDaysToDate(baseDate, tenorDays);
				this.context.binding.get("value").get("multiTenorDates").get(ind).set("instalmentMaturityDate", newMaturityDate);
			}
		}
	}

	this.ui.get("/DC_Templete1/4/tenorChange").setChecked(false);
};

this.setInstalmentTenorDays = function (ind) {
	var baseDateValue = this.context.binding.get("value").get("multiTenorDates").get(ind).get("instalmentBaseDate");
	var maturityDateValue = this.context.binding.get("value").get("multiTenorDates").get(ind).get("instalmentMaturityDate");

	if (!!baseDateValue && !!maturityDateValue) {
		var baseDate = new Date(baseDateValue);
		var maturityDate = new Date(maturityDateValue);
		this.ui.get("/DC_Templete1/4/Table1/instalmentMaturityDate[" + ind + "]").setValid(true);
		var timeDifference = maturityDate.getTime() - baseDate.getTime();
		var tenorDays = timeDifference / (1000 * 60 * 60 * 24);
		if (tenorDays < 0) {
			this.ui.get("/DC_Templete1/4/Table1/instalmentTenorDays[" + ind + "]").setValid(false, "Invalid Value, This field can not have a negative value");
			this.ui.get("/DC_Templete1/4/Table1/instalmentMaturityDate[" + ind + "]").setValid(false, "Instalment maturity date must be >= Instalment base date");
		} else {
			this.ui.get("/DC_Templete1/4/Table1/instalmentTenorDays[" + ind + "]").setValid(true);
			this.ui.get("/DC_Templete1/4/Table1/instalmentMaturityDate[" + ind + "]").setValid(true);
		}
		this.context.binding.get("value").get("multiTenorDates").get(ind).set("instalmentTenorDays", tenorDays);
	}
	//------------------------------------------
	//if(!!this.context.options.activityName.get("value") && this.context.options.activityName.get("value")  == "ACT04"){
	//this.ui.get("/DC_Templete1/7/transitTenorChange").setChecked(false);
	//
	//   var elementId = "datetimepicker-input-4:Table1:instalmentMaturityDate[" + ind + "]";
	//
	//    var element = document.getElementById(elementId);
	//
	//    element.addEventListener("change", function(event) {
	//	 	var value = event.target.value;
	//	 	console.log("Event target value:", value); // Log the value
	//		var tenorCustomEvent = new CustomEvent("changeTenorTransit", { detail: value });
	//		var maturityCustomEvent = new CustomEvent("changeMaturity", { detail: value });
	//
	//		document.dispatchEvent(maturityCustomEvent);
	//		document.dispatchEvent(tenorCustomEvent);
	//	});
	//		var triggerEvent = new Event('change');
	//		element.dispatchEvent(triggerEvent);
	//}
	//---------------------------------------------
};

// function to check if instalmentMaturityDate is unique - on change of multiTenorDates
this.areMaturityDatesUnique = function (me) {
	var msg = "Instalment Maturity Date must be unique";
	var tenorTable = this.ui.get("Table1");
	var dataList = tenorTable?.getData()?.items || [];
	// var target = caller == "base" ? "instalmentBaseDate" : "instalmentMaturityDate";
	var target = "instalmentMaturityDate";

	// Track occurrences of each formatted date
	var dateCounts = {};

	// Count occurrences of each date
	dataList.forEach(item => {
		// const formattedDate = caller == "base" ? formatDate(item.instalmentBaseDate) : formatDate(item.instalmentMaturityDate);
		const formattedDate = formatDate(item.instalmentMaturityDate);
		dateCounts[formattedDate] = (dateCounts[formattedDate] || 0) + 1;
	});

	// console.log("dateCounts", dateCounts);
	// Validate each row
	for (var i = 0; i < dataList.length; i++) {
		if (!dataList[i].instalmentMaturityDate) continue;
		const formattedDate = formatDate(dataList[i].instalmentMaturityDate);

		if (dateCounts[formattedDate] > 1) {
			// Invalid if the date appears more than once
			tenorTable.ui.getChild(target, i).setValid(false, msg);
		} else {
			tenorTable.ui.getChild(target, i).setValid(true);
			// console.log("setInstalmentCalculations", i, "m");
			this.setInstalmentCalculations(i, "m");
		}
	}
};

// Helper function to format the date to "yyyy-MM-dd"
function formatDate(date) {
	if (!date) return;
	const year = date.getFullYear();
	const month = String(date.getMonth() + 1).padStart(2, "0"); // Months are 0-indexed
	const day = String(date.getDate()).padStart(2, "0");
	return `${year}-${month}-${day}`;
}

//--------------------------------------------------------------------------------------------------------
// ON LOAD of FO view
this.setTenorColumnms = function () {
	const v1 = this.isMaker ? "V" : "R";
	const v2 = this.isAmend ? "R" : v1;
	const v3 = this.isAmend ? (this.isMaker ? "V" : "R") : "N";
	const liquidationStep = this.context.options.activityName?.get("value");
	const isLiqMaker = liquidationStep === "liqMkr";
	const isLiqCheker = liquidationStep === "liqChk"; 

	const isPosition = this.context.options.positionSearch?.get("value") === true;
	const v4 = isLiqMaker || isLiqCheker ? (isLiqMaker ? "V" : "R") : isPosition ? "R" : "N"; // Liquidation Amount

	if (this.tenorTable) {
		this.tenorTable.context.options.showDeleteButton.set("value", this.isMaker);
		this.tenorTable.context.options.showAddButton.set("value", this.isMaker);

		if (isLiqMaker || isLiqCheker) {
			this.tenorTable.setEnabled(isLiqMaker);
			this.tenorTable.context.options.showDeleteButton.set("value", false);
			this.tenorTable.context.options.showAddButton.set("value", false);
		}
	}

	console.log("isLiqMaker", isLiqMaker, "isLiqCheker", isLiqCheker, "isAmend", this.isAmend, "isMaker", this.isMaker, "v4", v4, "positionSearch", isPosition, "tenorTable enabled", this.tenorTable?.isEnabled());

	// set tenor table columns
	var tableColumns = [
		{ renderAs: "V", visibility: v1, sortable: false, options: "", css: "", width: "", label: "", showLabel: false, rearrangeColumn: false },
		{ renderAs: "V", visibility: v1, sortable: false, options: "", css: "", width: "", label: "", showLabel: false, rearrangeColumn: false },
		{ renderAs: "V", visibility: v1, sortable: false, options: "", css: "", width: "", label: "", showLabel: false, rearrangeColumn: false },
		{ renderAs: "V", visibility: v2, sortable: false, options: "", css: "", width: "", label: "", showLabel: false, rearrangeColumn: false },
		{ renderAs: "V", visibility: v3, sortable: false, options: "", css: "", width: "", label: "", showLabel: false, rearrangeColumn: false },
		{ renderAs: "V", visibility: v4, sortable: false, options: "", css: "", width: "", label: "", showLabel: false, rearrangeColumn: false },
	];

	this.context.options.tenorTableColumns?.set("value", tableColumns);
};

this.setAmendRebateVis = function () {
	this.tenorTable.setVisible(this.isMultiTenor, true);
	this.contRebate?.setVisible(false, true);
	if (this.isAmend) {
		this.contRebate?.setVisible(true);
		this.contRebate?.setEnabled(this.isMaker);
		if (this.isMultiTenor) {
			this.contRebate?.setEnabled(false);
			// tenor table
			this.tenorTable.setVisible(true);
			this.tenorTable.setEnabled(this.isMaker);
			// disable add and delete split
			this.tenorTable?.context.options.showDeleteButton.set("value", false);
			this.tenorTable?.context.options.showAddButton.set("value", false);
		}
		this.setBulkREADONLY(this.listOfFields, false);
	}
};

// ON CHANGE of tenor rebate
// validate tenor rebate against split amount
this.validateTenorRebate = function (me) {
	var index = me.ui.getIndex();

	if (me.getData() < 0) {
		me.setData(0);
		return;
	} else if (me.getData() > this.tenorTable.ui.getChild("Text2", index)?.getData()) {
		me.setValid(false, "Rebate Amount must be < or = Split Amount");
		return;
	} else {
		me.setData(Number(me.getData()?.toFixed(2)));
		me.setValid(true);
	}

	// var tenorTable = this.context.binding.get("value").get("multiTenorDates").items;
	var tenorTable = this.tenorTable?.getData().items;
	var dataList = tenorTable.map(item => item.splitRebateAmnt) || [];
	//	me.setData(me.getData());
	// sum of all splitRebateAmnt
	var sum = 0;
	for (var i = 0; i < dataList.length; i++) {
		sum += dataList[i];
	}
	this.contRebate?.setData(sum);
};

this.validateSplitAmnt = function (me) {
	if (me.getData() < 0) {
		me.setData(0);
		return;
	} else {
		me.setData(Number(me.getData()?.toFixed(2)));
		me.setValid(true);
	}
};

// ON CHANGE of contract rebate
// validate contract rebate against contract amount
this.validateContRebate = function () {
	var sum = 0.0;
	var tenors = this.tenorTable?.getData().items;
	var outstandingAmount = this.context.binding.get("value").get("outstandingAmount") || 0;
	var contRebate = this.contRebate;

	if (contRebate.getData() < 0) {
		contRebate.setData(0);
		contRebate.setValid(false, "Contract Rebate Amount must > 0");
		return false;
	}

	if (contRebate.getData() >= outstandingAmount) {
		contRebate.setValid(false, "Contract Rebate Amount must be < Outstanding Amount");
		return false;
	}

	if (this.context.options.paymentTermValue?.get("value") && this.context.options.paymentTermValue?.get("value") == "004" && tenors.length > 0) {
		for (var i = 0; i < tenors.length; i++) {
			// validate sum of all split rebates must equal contract rebate
			sum += tenors[i].splitRebateAmnt;
		}
		if (sum != contRebate.getData()) {
			contRebate.setValid(false, "Contract Rebate Amount must eaqual Sum of all Split Rebates");
			return false;
		}
	}

	contRebate.setValid(true);
	return true;
};
// Helper functions---------------------------------------------------------------------------------

this.fieldsInit = function () {
	this.discount = this.getFieldById("discount1");
	this.contRebate = this.getFieldById("contractRebateAmnt");
	this.tenorTable = this.getFieldById("Table1");
	this.tenorRebate = this.getFieldById("Table1/rebate"); // rebate
	this.splitAmnt = this.getFieldById("Table1/Text2"); // Text2
	this.extCharge = this.getFieldById("extraCharges1");
	// Financial Branch view
	this.docAmnt = this.getViewByPath("/DC_Templete1/2/documentAmount");
	this.advAmnt = this.getViewByPath("/DC_Templete1/2/amountAdvanced");
	this.paymentTerms = this.getViewByPath("/DC_Templete1/0/paymentTerms");
	this.submitBtn = this.getViewByPath("/DC_Templete1/submit");
	this.request = this.context.options.requestType.get("value");
	this.isMaker = this.context.options.financialDetailsFOVis.get("value")?.toLowerCase() == "editable" ? true : false || false;
	this.isMultiTenor = this.context.options.paymentTermValue?.get("value") == "004" ? true : false;
	this.isAmend = this.request.toLowerCase().includes("amend") || false;
	// Contract Creation view
	this.prodCode = this.getViewByPath("/DC_Templete1/7/productCode");
	this.contAmnt = this.getViewByPath("/DC_Templete1/7/amount");

	this.listOfFields = [this.discount, this.extCharge, this.advAmnt, this.docAmnt, this.paymentTerms, this.prodCode];
};

this.setBulkREADONLY = function (listOfFields, value) {
	if (listOfFields && listOfFields.length > 0) {
		listOfFields.forEach(function (field) {
			if (field) {
				field?.setEnabled(value);
			}
		});
	}
};

this.getViewByPath = function getViewByPath(path) {
	return bpmext.ui.getView(path) || null;
};

this.getFieldById = function (path) {
	return this.ui.get(path) || null;
};

// Helper function to get the date part only without time
function getDateOnly(date) {
	const d = new Date(date);
	return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

// reusable function to prevent negative value on input (only works on input not on change)
this.preventNegativeInput = function (me) {
	// Add an event listener to the input field of the Integer control
	me.context.element.addEventListener("input", function (event) {
		// Get the current value of the input
		var currentValue = event.target.value;

		// If the value starts with a '-' prevent it
		if (currentValue.startsWith("-")) {
			event.target.value = currentValue.replace("-", "");
		}
	});
};
